// Run with Bun. Fixtures are generated by the actual UI reducer, not a second model.
import { createLayoutState, layoutReducer, type LayoutAction } from "../src/state/layout";
import type { LayoutState, PaneContent, WorkspaceTab } from "../src/lib/types";
import type { PaneNode } from "../src/state/paneTree";

const terminal = (id: string): WorkspaceTab => ({ id, kind: "terminal", label: id, sessionId: `pty-${id}` });
const initial = () => {
  let state = createLayoutState([terminal("one"), terminal("two")], "one");
  state = layoutReducer(state, { type: "SPLIT_PANE", tabId: "one", targetLeafId: "leaf-init", newLeafId: "second", sessionId: "pty-second", direction: "horizontal" });
  return state;
};
function project(state: LayoutState) {
  const tree = (node: PaneNode, content: Record<string, PaneContent>): unknown => node.type === "split"
    ? { type: "split", dir: node.direction, ratio: node.ratio, a: tree(node.first, content), b: tree(node.second, content) }
    : { type: "leaf", content: content[node.leafId]?.kind === "browser"
        ? { kind: "browser", url: (content[node.leafId] as Extract<PaneContent, { kind: "browser" }>).browser.url }
        : { kind: "terminal", backendSessionId: (content[node.leafId] as Extract<PaneContent, { kind: "terminal" }>)?.sessionId ?? "" } };
  return state.tabs.map((tab) => ({ tabId: tab.id, label: "customLabel" in tab ? tab.customLabel ?? tab.label : tab.label, pinned: tab.pinned ?? false,
    paneTree: tree(state.layoutsByTabId[tab.id].root, state.layoutsByTabId[tab.id].contentsByLeafId ?? {}) }));
}
// createLayoutState uses the stable initial group identity.
const group = initial().focusedGroupId!;
const pairs: { action: LayoutAction; intent: Record<string, unknown> }[] = [
  { action: { type: "ADD_TAB", tab: terminal("three"), activate: true }, intent: { type: "ADD_TAB_WITH_SESSION", tabId: "three", label: "three", content: { kind: "terminal", backendSessionId: "pty-three" }, activate: true } },
  { action: { type: "CLOSE_TAB", tabId: "two" }, intent: { type: "CLOSE_TAB", tabId: "two" } },
  { action: { type: "REORDER_TAB", tabId: "two", targetIndex: 0 }, intent: { type: "REORDER_TAB", tabId: "two", targetIndex: 0 } },
  { action: { type: "RENAME_TAB", tabId: "one", label: "renamed" }, intent: { type: "RENAME_TAB", tabId: "one", label: "renamed" } },
  { action: { type: "SET_TAB_PINNED", tabId: "one", pinned: true }, intent: { type: "SET_TAB_PINNED", tabId: "one", pinned: true } },
  { action: { type: "SPLIT_PANE", tabId: "one", targetLeafId: "second", newLeafId: "third", sessionId: "pty-third", direction: "vertical" }, intent: { type: "SPLIT_PANE", tabId: "one", targetNodeId: 2, dir: "vertical", first: false, content: { kind: "terminal", backendSessionId: "pty-third" } } },
  { action: { type: "MOVE_TAB_TO_GROUP", sourceTabId: "two", targetGroupId: group, targetIndex: 0 }, intent: { type: "MOVE_TAB_TO_GROUP", sourceTabId: "two", targetGroupId: group, targetIndex: 0 } },
  { action: { type: "MOVE_TAB_TO_SPLIT", sourceTabId: "two", targetGroupId: group, direction: "vertical" }, intent: { type: "MOVE_TAB_TO_SPLIT", sourceTabId: "two", targetGroupId: group, dir: "vertical", first: false } },
  { action: { type: "DETACH_PANE_TO_TAB", sourceTabId: "one", leafId: "second", newTab: terminal("three"), targetGroupId: group }, intent: { type: "DETACH_PANE_TO_TAB", sourceTabId: "one", nodeId: 2, tabId: "three", label: "three", targetGroupId: group } },
  { action: { type: "CLOSE_PANE", tabId: "one", leafId: "second" }, intent: { type: "CLOSE_PANE", tabId: "one", nodeId: 2 } },
  { action: { type: "ACTIVATE_TAB", tabId: "two" }, intent: { type: "ACTIVATE_TAB", tabId: "two" } },
  { action: { type: "FOCUS_PANE", tabId: "one", leafId: "leaf-init" }, intent: { type: "FOCUS_PANE", tabId: "one", nodeId: 1 } },
  { action: { type: "SET_PANE_RATIO", tabId: "one", path: "", ratio: 0.7, isolated: true }, intent: { type: "SET_PANE_RATIO", tabId: "one", path: "", ratio: 0.7 } },
  { action: { type: "EQUALIZE_PANE_RUN", tabId: "one", path: "" }, intent: { type: "EQUALIZE_PANE_RUN", tabId: "one", path: "" } },
  { action: { type: "EQUALIZE_PANES", tabId: "one" }, intent: { type: "EQUALIZE_PANES", tabId: "one" } },
  { action: { type: "SWAP_PANES", tabId: "one", sourceLeafId: "leaf-init", targetLeafId: "second" }, intent: { type: "SWAP_PANES", tabId: "one", sourceNodeId: 1, targetNodeId: 2 } },
  { action: { type: "TOGGLE_PANE_EXPANDED", tabId: "one", leafId: "second" }, intent: { type: "TOGGLE_PANE_EXPANDED", tabId: "one", nodeId: 2 } },
];
const cases = pairs.map(({ action, intent }) => {
  const before = initial();
  // Each tab's historical initial visual id can repeat; migration remaps by traversal.
  const sessions = Object.fromEntries(["one", "two", "second", "third"].map((id) => [`pty-${id}`, { backendSessionId: `pty-${id}` }]));
  return { intent, session: { layout: before, terminalSessions: sessions }, expected: project(layoutReducer(before, action)) };
});
console.log(JSON.stringify(cases));
